<?php

// GENERATED by scripts/build-updater from core/src/Updater — do not edit. The update guard (spec §7).

declare(strict_types=1);

namespace Thallo\ShippedUpdater\Guard;

// ---- Paths ----
/**
 * Every file the updater reads or writes, from the site's base path. Dependency-free: this class is
 * concatenated into bin/thallo-updater and bootstrap/update-guard.php (scripts/build-updater).
 */
final class Paths
{
    public function __construct(public readonly string $base)
    {
    }

    public function dir(): string
    {
        return $this->base . '/storage/framework/updates';
    }
    public function operation(): string
    {
        return $this->dir() . '/operation.json';
    }
    public function stateLock(): string
    {
        return $this->dir() . '/state.lock';
    }
    public function runLock(): string
    {
        return $this->dir() . '/run.lock';
    }
    public function admissionLock(): string
    {
        return $this->dir() . '/admission.lock';
    }
    public function closedFlag(): string
    {
        return $this->dir() . '/closed.flag';
    }
    public function runnerReport(): string
    {
        return $this->dir() . '/runner.json';
    }
    public function verifySecret(): string
    {
        return $this->dir() . '/verify.secret';
    }
    public function proofMarker(): string
    {
        return $this->dir() . '/.proof';
    }
    public function opDir(string $id): string
    {
        return $this->dir() . '/' . $id;
    }
    public function backupDir(string $id): string
    {
        return $this->base . '/storage/backups/update-' . $id;
    }
    public function log(string $id): string
    {
        return $this->base . '/storage/logs/update-' . $id . '.log';
    }
}

// ---- FileLock ----
/** flock helpers. A lock lives as long as its handle (or the process); release() closes it. */
final class FileLock
{
    /** @return resource|null */
    public static function exclusive(string $path, bool $block = true)
    {
        $h = fopen($path, 'c');
        if ($h === false) {
            throw new \RuntimeException("Cannot open lock {$path}");
        }
        if (!flock($h, $block ? LOCK_EX : LOCK_EX | LOCK_NB)) {
            fclose($h);
            return null;
        }
        return $h;
    }

    /** @return resource|null */
    public static function shared(string $path)
    {
        $h = @fopen($path, 'c');
        if ($h === false) {
            return null;
        }
        if (!flock($h, LOCK_SH | LOCK_NB)) {
            fclose($h);
            return null;
        }
        return $h;
    }

    /** @param resource $handle */
    public static function release($handle): void
    {
        flock($handle, LOCK_UN);
        fclose($handle);
    }

    public static function withExclusive(string $path, callable $fn): mixed
    {
        $h = self::exclusive($path);
        try {
            return $fn();
        } finally {
            self::release($h);
        }
    }
}

// ---- AtomicFile ----
/** Whole-file writes that are never seen half-written: temp file, fsync, rename. */
final class AtomicFile
{
    public static function write(string $path, string $contents, int $mode = 0640): void
    {
        $tmp = $path . '.tmp-' . getmypid() . '-' . bin2hex(random_bytes(3));
        $h = fopen($tmp, 'x');
        if ($h === false) {
            throw new \RuntimeException("Cannot write {$tmp}");
        }
        fwrite($h, $contents);
        fflush($h);
        if (function_exists('fsync')) {
            fsync($h);
        }
        fclose($h);
        chmod($tmp, $mode);
        if (!rename($tmp, $path)) {
            @unlink($tmp);
            throw new \RuntimeException("Cannot replace {$path}");
        }
    }

    public static function writeJson(string $path, array $data, int $mode = 0640): void
    {
        $json = json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
        self::write($path, $json . "\n", $mode);
    }

    public static function readJson(string $path): ?array
    {
        if (!is_file($path)) {
            return null;
        }
        $data = json_decode((string) file_get_contents($path), true);
        return is_array($data) ? $data : null;
    }
}

// ---- Status ----
final class Status
{
    public const REQUESTED = 'requested';
    public const RUNNING = 'running';
    public const SUCCEEDED = 'succeeded';
    public const FAILED = 'failed';
    public const ROLLED_BACK = 'rolled_back';
    public const RECOVERY_REQUIRED = 'recovery_required';
    public const RECOVERED_BY_OWNER = 'recovered_by_owner';
    public const CANCELLED = 'cancelled';

    public static function isTerminal(string $status): bool
    {
        $terminal = [self::SUCCEEDED, self::FAILED, self::ROLLED_BACK, self::RECOVERED_BY_OWNER, self::CANCELLED];
        return in_array($status, $terminal, true);
    }
}

// ---- UpdateRefused ----
final class UpdateRefused extends \RuntimeException
{
    public function __construct(public readonly string $reason)
    {
        parent::__construct($reason);
    }
}

// ---- Fenced ----
/** A write by a runner that no longer owns the operation (spec §5): it is refused, never applied. */
final class Fenced extends \RuntimeException
{
}

// ---- OperationStore ----
/**
 * The one update operation (spec §5). Every transition is a compare-and-set under a short exclusive
 * lock on state.lock, on the operation id, status and owner the caller expects. A runner that lost
 * ownership (it was paused, found dead, or the operation finished) gets Fenced, never a write.
 */
final class OperationStore
{
    public const FORMAT = 1;
    public const RECOVERY_OPTIONS = ['rollback', 'retry_provision', 'reopen'];

    public function __construct(private readonly Paths $paths, private readonly \Closure $now)
    {
    }

    public function current(): ?array
    {
        return AtomicFile::readJson($this->paths->operation());
    }

    /** @return array{0: array, 1: string} */
    public function start(string $target, string $from, string $requestedBy): array
    {
        return $this->locked(function () use ($target, $from, $requestedBy): array {
            $op = $this->current();
            if ($op !== null && $op['status'] === Status::RECOVERY_REQUIRED) {
                throw new UpdateRefused('recovery_required');
            }
            if ($op !== null && !Status::isTerminal($op['status'])) {
                throw new UpdateRefused('in_progress');
            }
            $token = bin2hex(random_bytes(32));
            $op = [
                'format' => self::FORMAT,
                'id' => gmdate('YmdHis', ($this->now)()) . '-' . bin2hex(random_bytes(3)),
                'target' => $target,
                'from' => $from,
                'status' => Status::REQUESTED,
                'step' => null,
                'steps' => [],
                'requested_by' => $requestedBy,
                'requested_at' => ($this->now)(),
                'token_hash' => hash('sha256', $token),
                'owner' => null,
                'pid' => null,
                'pgid' => null,
                'heartbeat_at' => null,
                'provision_started' => false,
                'reopen_ready_at' => null,
                'journal' => [],
                'backup' => null,
                'provision_manifest' => null,
                'recovery_request' => null,
                'recovering' => null,
                'error' => null,
            ];
            $this->write($op);
            return [$op, $token];
        });
    }

    public function claim(string $id, int $pid, ?int $pgid): ?array
    {
        return $this->transition($id, static fn (array $op): bool => $op['status'] === Status::REQUESTED, $pid, $pgid);
    }

    public function claimRecovery(string $id, int $pid, ?int $pgid): ?array
    {
        return $this->transition(
            $id,
            static fn (array $op): bool => $op['status'] === Status::RECOVERY_REQUIRED
                && $op['recovery_request'] !== null,
            $pid,
            $pgid,
            true,
        );
    }

    public function takeOver(string $id, string $deadOwner, int $pid, ?int $pgid): ?array
    {
        return $this->transition(
            $id,
            static fn (array $op): bool => $op['status'] === Status::RUNNING
                && hash_equals((string) $op['owner'], $deadOwner),
            $pid,
            $pgid,
        );
    }

    public function cancel(string $id): bool
    {
        return $this->locked(function () use ($id): bool {
            $op = $this->current();
            if ($op === null || $op['id'] !== $id || $op['status'] !== Status::REQUESTED) {
                return false;
            }
            $op['status'] = Status::CANCELLED;
            $this->write($op);
            return true;
        });
    }

    public function update(string $id, string $owner, callable $mutate): array
    {
        return $this->locked(function () use ($id, $owner, $mutate): array {
            $op = $this->owned($id, $owner);
            $op = $mutate($op);
            $op['id'] = $id; // a mutation can never move the write to another operation
            $op['owner'] = $owner;
            $this->write($op);
            return $op;
        });
    }

    public function finish(string $id, string $owner, string $status, ?string $error = null): array
    {
        return $this->update($id, $owner, static function (array $op) use ($status, $error): array {
            $op['status'] = $status;
            $op['error'] = $error;
            $op['recovery_request'] = null;
            $op['recovering'] = null;
            return $op;
        });
    }

    public function verifyToken(string $token): bool
    {
        $op = $this->current();
        return $op !== null && $token !== '' && hash_equals((string) $op['token_hash'], hash('sha256', $token));
    }

    public function rotateToken(string $id): ?string
    {
        return $this->locked(function () use ($id): ?string {
            $op = $this->current();
            if ($op === null || $op['id'] !== $id) {
                return null;
            }
            $token = bin2hex(random_bytes(32));
            $op['token_hash'] = hash('sha256', $token);
            $this->write($op);
            return $token;
        });
    }

    public function requestRecovery(string $token, string $option): bool
    {
        return $this->locked(function () use ($token, $option): bool {
            $op = $this->current();
            if ($op === null || $token === '' || !hash_equals((string) $op['token_hash'], hash('sha256', $token))) {
                return false;
            }
            return $this->recordRecovery($op, $option);
        });
    }

    public function requestRecoveryAsOwner(string $id, string $option): bool
    {
        return $this->locked(function () use ($id, $option): bool {
            $op = $this->current();
            return $op !== null && $op['id'] === $id && $this->recordRecovery($op, $option);
        });
    }

    private function recordRecovery(array $op, string $option): bool
    {
        if (!in_array($option, self::RECOVERY_OPTIONS, true) || $op['status'] !== Status::RECOVERY_REQUIRED) {
            return false;
        }
        $op['recovery_request'] = $option;
        $this->write($op);
        return true;
    }

    private function transition(string $id, \Closure $allowed, int $pid, ?int $pgid, bool $recovery = false): ?array
    {
        return $this->locked(function () use ($id, $allowed, $pid, $pgid, $recovery): ?array {
            $op = $this->current();
            if ($op === null || $op['id'] !== $id || !$allowed($op)) {
                return null;
            }
            if ($recovery) {
                $op['recovering'] = $op['recovery_request'];
                $op['recovery_request'] = null;
            }
            $op['status'] = Status::RUNNING;
            $op['owner'] = bin2hex(random_bytes(16));
            $op['pid'] = $pid;
            $op['pgid'] = $pgid;
            $op['heartbeat_at'] = ($this->now)();
            $this->write($op);
            return $op;
        });
    }

    private function owned(string $id, string $owner): array
    {
        $op = $this->current();
        if (
            $op === null
            || $op['id'] !== $id
            || $op['status'] !== Status::RUNNING
            || !hash_equals((string) $op['owner'], $owner)
        ) {
            throw new Fenced("Operation {$id} is no longer owned by this runner");
        }
        return $op;
    }

    private function write(array $op): void
    {
        AtomicFile::writeJson($this->paths->operation(), $op);
    }

    private function locked(callable $fn): mixed
    {
        if (!is_dir($this->paths->dir())) {
            mkdir($this->paths->dir(), 0770, true);
        }
        return FileLock::withExclusive($this->paths->stateLock(), $fn);
    }
}

// ---- Barrier ----
/**
 * Closing the site and the barrier (spec §7). Admitted web requests and console processes hold a
 * shared flock on admission.lock for their whole life; the runner's exclusive lock is granted only
 * when none remains. closed.flag keeps new work out. Not final: tests reach admitAfterFirstCheck().
 */
class Barrier
{
    public function __construct(protected readonly Paths $paths)
    {
    }

    public function isClosed(): bool
    {
        return is_file($this->paths->closedFlag());
    }

    public function close(): void
    {
        AtomicFile::write($this->paths->closedFlag(), gmdate('c') . "\n", 0644);
    }

    public function open(): void
    {
        @unlink($this->paths->closedFlag());
    }

    /** @return resource|null */
    public function admit()
    {
        if ($this->isClosed()) {
            return null;
        }
        return $this->admitAfterFirstCheck();
    }

    /** @return resource|null */
    protected function admitAfterFirstCheck()
    {
        $h = FileLock::shared($this->paths->admissionLock());
        if ($h === null) {
            return null; // the runner holds the barrier
        }
        if ($this->isClosed()) {
            FileLock::release($h);
            return null;
        }
        return $h;
    }

    /** @return resource|null */
    public function acquire(int $timeout, \Closure $now, \Closure $sleep)
    {
        $start = $now();
        while (true) {
            $h = FileLock::exclusive($this->paths->admissionLock(), false);
            if ($h !== null) {
                return $h;
            }
            if ($now() - $start >= $timeout) {
                return null;
            }
            $sleep();
        }
    }
}

// ---- GuardResponse ----
final class GuardResponse
{
    /** @param array<string,string> $headers */
    public function __construct(public int $status, public array $headers, public string $body)
    {
    }

    public static function json(int $status, array $data): self
    {
        $headers = ['Content-Type' => 'application/json', 'Cache-Control' => 'no-store'];
        return new self($status, $headers, json_encode($data, JSON_UNESCAPED_SLASHES) ?: '{}');
    }

    public function send(): void
    {
        http_response_code($this->status);
        foreach ($this->headers as $name => $value) {
            header($name . ': ' . $value);
        }
        echo $this->body;
    }
}

// ---- RecoveryPage ----
/**
 * The /_update page (spec §11): one self-contained document, served by the guard, that never touches
 * the application, vendor/ or the admin bundle — so it loads during the vendor gap, after a failed
 * provision, and after a refresh. It holds no data; everything comes from /_update/status with the
 * operation token kept in sessionStorage.
 */
final class RecoveryPage
{
    // phpcs:disable Generic.Files.LineLength.TooLong -- inline CSS/JS of a self-contained page
    public static function html(): string
    {
        return <<<'HTML'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Thallo update</title>
<style>
:root{--bg:#f7f8fa;--card:#fff;--text:#1d2330;--muted:#5d6678;--line:#dfe3ea;--ok:#2e7d4f;--warn:#a5620c;--bad:#b3261e;--accent:#3557b7}
@media (prefers-color-scheme:dark){:root{--bg:#12151b;--card:#1b2029;--text:#e6e9ef;--muted:#9aa3b2;--line:#2c3340;--ok:#5bbf86;--warn:#e0a74a;--bad:#ef7a72;--accent:#8ea8ff}}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif;padding:32px 16px}
main{max-width:46rem;margin:0 auto;display:grid;gap:16px}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:20px}
h1{font-size:1.35rem;margin:0 0 4px;text-wrap:balance}
p{margin:0}
.muted{color:var(--muted)}
ol{margin:0;padding:0;list-style:none;display:grid;gap:6px}
li{display:flex;justify-content:space-between;gap:12px;font-variant-numeric:tabular-nums}
li .s-done{color:var(--ok)} li .s-running{color:var(--accent)}
pre{margin:0;max-height:22rem;overflow:auto;background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:12px;font:12px/1.45 ui-monospace,Menlo,monospace;white-space:pre-wrap;word-break:break-word}
code{font:13px ui-monospace,Menlo,monospace;word-break:break-all}
.warn{color:var(--warn)} .bad{color:var(--bad)} .ok{color:var(--ok)}
.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
button{font:inherit;border:1px solid var(--line);background:var(--card);color:var(--text);border-radius:8px;padding:8px 14px;cursor:pointer}
button.primary{background:var(--accent);border-color:var(--accent);color:#fff}
input{font:inherit;width:100%;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--text)}
[hidden]{display:none!important}
</style>
</head>
<body>
<main>
  <section class="card" id="head"><h1 id="title">Thallo update</h1><p class="muted" id="subtitle">Checking…</p></section>
  <section class="card" id="token-card" hidden>
    <p>Enter the update token. On the server, <code>php bin/thallo-updater token</code> prints a new one.</p>
    <form id="token-form" class="actions"><input id="token-input" autocomplete="off" aria-label="Update token"><button class="primary">Continue</button></form>
  </section>
  <section class="card" id="busy" hidden><p class="warn">The server is busy — still checking.</p></section>
  <section class="card" id="steps-card" hidden><ol id="steps"></ol></section>
  <section class="card" id="recovery" hidden>
    <p id="recovery-error" class="bad"></p>
    <p class="muted" style="margin-top:8px">The database is never restored automatically. Backup: <code id="backup-path"></code></p>
    <p class="muted">To restore it: <code id="restore-cmd"></code></p>
    <div class="actions">
      <button data-option="rollback">Roll back the code</button>
      <button data-option="retry_provision">Retry provision</button>
      <button data-option="reopen">Reopen the site</button>
    </div>
    <div id="reopen-confirm" hidden style="margin-top:12px">
      <p>Type <code>REOPEN</code> to reopen the site as it is now.</p>
      <div class="actions"><input id="reopen-input" autocomplete="off" aria-label="Type REOPEN"><button class="primary" id="reopen-go">Reopen</button></div>
    </div>
    <p id="waiting" class="muted" hidden style="margin-top:8px">Waiting for the runner (up to a minute)…</p>
  </section>
  <section class="card" id="log-card" hidden><pre id="log"></pre></section>
  <p class="muted"><a href="/admin" style="color:var(--accent)">Back to the admin</a></p>
</main>
<script>
(function () {
  var KEY = 'thallo.update.token';
  var $ = function (id) { return document.getElementById(id); };
  var token = '';
  try { token = sessionStorage.getItem(KEY) || ''; } catch (e) {}
  var TITLES = {
    requested: function (o) { return 'Waiting to update to ' + o.target; },
    running: function (o) { return 'Updating to ' + o.target; },
    succeeded: function (o) { return 'Updated to ' + o.target; },
    failed: function () { return 'Update failed — nothing changed'; },
    rolled_back: function (o) { return 'Rolled back to ' + o.from; },
    recovery_required: function () { return 'Your site needs attention'; },
    recovered_by_owner: function () { return 'The site is open again'; },
    cancelled: function () { return 'The update was cancelled'; }
  };
  function show(id, on) { $(id).hidden = !on; }
  function askToken() { show('token-card', true); show('busy', false); }
  $('token-form').addEventListener('submit', function (e) {
    e.preventDefault();
    token = $('token-input').value.trim();
    try { sessionStorage.setItem(KEY, token); } catch (err) {}
    show('token-card', false);
    poll();
  });
  function duration(s) {
    if (!s.started_at) { return ''; }
    var end = s.ended_at || Math.floor(Date.now() / 1000);
    return Math.max(0, end - s.started_at) + ' s';
  }
  function render(data) {
    var o = data.operation || {};
    show('busy', false);
    if (!o.status) {
      $('title').textContent = 'No update in progress';
      $('subtitle').textContent = '';
      return;
    }
    $('title').textContent = (TITLES[o.status] || function () { return o.status; })(o);
    $('subtitle').textContent = o.error || (o.step ? 'Step: ' + o.step : '');
    var list = $('steps');
    list.textContent = '';
    (o.steps || []).forEach(function (s) {
      var li = document.createElement('li');
      var name = document.createElement('span');
      name.textContent = s.name.replace(/_/g, ' ');
      var state = document.createElement('span');
      state.className = 's-' + s.status;
      state.textContent = (s.status === 'done' ? '✓ ' : '… ') + duration(s);
      li.appendChild(name);
      li.appendChild(state);
      list.appendChild(li);
    });
    show('steps-card', (o.steps || []).length > 0);
    var log = $('log');
    var atEnd = log.scrollTop + log.clientHeight >= log.scrollHeight - 4;
    log.textContent = data.log || '';
    if (atEnd) { log.scrollTop = log.scrollHeight; }
    show('log-card', !!data.log);
    var recovering = o.status === 'recovery_required';
    show('recovery', recovering);
    if (recovering) {
      var path = (o.backup && o.backup.path) || '(no backup was taken)';
      $('recovery-error').textContent = o.error || '';
      $('backup-path').textContent = path;
      $('restore-cmd').textContent = 'pg_restore --clean --if-exists --dbname <database> ' + path + '/database.dump';
      show('waiting', !!o.recovery_request);
    }
  }
  function request(option, confirm) {
    var body = { option: option };
    if (confirm) { body.confirm = confirm; }
    fetch('/_update/recover', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-thallo-update-token': token },
      body: JSON.stringify(body),
      cache: 'no-store'
    }).then(function (r) { if (r.status === 202) { show('waiting', true); } });
  }
  document.querySelectorAll('[data-option]').forEach(function (b) {
    b.addEventListener('click', function () {
      var option = b.getAttribute('data-option');
      if (option === 'reopen') { show('reopen-confirm', true); return; }
      request(option);
    });
  });
  $('reopen-go').addEventListener('click', function () {
    if ($('reopen-input').value.trim() === 'REOPEN') { request('reopen', 'REOPEN'); show('reopen-confirm', false); }
  });
  function poll() {
    if (!token) { askToken(); return; }
    fetch('/_update/status', { headers: { 'x-thallo-update-token': token }, cache: 'no-store' })
      .then(function (r) {
        if (r.status === 403) { askToken(); return null; }
        if (!r.ok) { throw new Error('busy'); }
        return r.json();
      })
      .then(function (data) { if (data) { render(data); setTimeout(poll, 2000); } })
      .catch(function () { show('busy', true); setTimeout(poll, 2000); });
  }
  poll();
})();
</script>
</body>
</html>
HTML;
    }
    // phpcs:enable Generic.Files.LineLength.TooLong
}

// ---- Guard ----
/**
 * The guard (spec §7), included by public/index.php and glueful before bootstrap/app.php. Plain
 * PHP: it must work while vendor/ is being replaced. Guard routes (/_update…) never boot the
 * application and never take the barrier; everything else is admitted or refused here.
 */
final class Guard
{
    /** @var resource|null held for the request's or process's life */
    private static $process = null;
    /** @var resource|null */
    private $held = null;
    private \Closure $sleep;

    public function __construct(
        private readonly Paths $paths,
        private readonly OperationStore $ops,
        private readonly Barrier $barrier,
        ?\Closure $sleep = null,
    ) {
        $this->sleep = $sleep ?? static function (): void {
            sleep(5);
        };
    }

    public static function boot(string $base): void
    {
        $paths = new Paths($base);
        $guard = new self($paths, new OperationStore($paths, static fn (): int => time()), new Barrier($paths));
        if (PHP_SAPI === 'cli') {
            $env = getenv();
            $code = $guard->console($_SERVER['argv'] ?? [], is_array($env) ? $env : []);
            if ($code !== null) {
                exit($code);
            }
        } else {
            $headers = [];
            foreach ($_SERVER as $k => $v) {
                if (is_string($v) && str_starts_with($k, 'HTTP_')) {
                    $headers[strtolower(str_replace('_', '-', substr($k, 5)))] = $v;
                }
            }
            $path = parse_url((string) ($_SERVER['REQUEST_URI'] ?? '/'), PHP_URL_PATH);
            $r = $guard->web(
                (string) ($_SERVER['REQUEST_METHOD'] ?? 'GET'),
                is_string($path) ? $path : '/',
                $headers,
                (string) file_get_contents('php://input'),
            );
            if ($r !== null) {
                $r->send();
                exit;
            }
        }
        self::$process = $guard->held();
    }

    /** @param array<string,string> $headers */
    public function web(string $method, string $path, array $headers, string $body): ?GuardResponse
    {
        if ($path === '/_update' || str_starts_with($path, '/_update/')) {
            return $this->route($method, $path, $headers, $body);
        }
        $this->held = $this->barrier->admit();
        if ($this->held !== null) {
            return null;
        }
        if ($path === '/health') {
            return GuardResponse::json(503, ['status' => 'updating']);
        }
        $headers = [
            'Content-Type' => 'text/html; charset=utf-8',
            'Retry-After' => '120',
            'Cache-Control' => 'no-store',
        ];
        return new GuardResponse(503, $headers, self::closedPage());
    }

    /** @param list<string> $argv @param array<string,string> $env */
    public function console(array $argv, array $env): ?int
    {
        if (($env['THALLO_UPDATE_CHILD'] ?? '') === '1') {
            return null;
        }
        $command = $argv[1] ?? '';
        if ($command === 'queue:work') {
            while (($this->held = $this->barrier->admit()) === null) {
                ($this->sleep)();
            }
            return null;
        }
        $this->held = $this->barrier->admit();
        if ($this->held !== null) {
            return null;
        }
        if ($command === 'queue:scheduler') {
            return 0;
        }
        fwrite(STDERR, "Thallo is being updated; try again when it finishes (see /_update).\n");
        return 1;
    }

    /** @return resource|null */
    public function held()
    {
        return $this->held;
    }

    /** @param array<string,string> $headers */
    private function route(string $method, string $path, array $headers, string $body): GuardResponse
    {
        if ($path === '/_update' && $method === 'GET') {
            $headers = ['Content-Type' => 'text/html; charset=utf-8', 'Cache-Control' => 'no-store'];
            return new GuardResponse(200, $headers, RecoveryPage::html());
        }
        if ($path === '/_update/verify' && $method === 'POST') {
            return $this->verify($headers, $body);
        }
        $token = $headers['x-thallo-update-token'] ?? '';
        if (!$this->ops->verifyToken($token)) {
            return GuardResponse::json(403, ['error' => 'token']);
        }
        if ($path === '/_update/status' && $method === 'GET') {
            $op = $this->ops->current() ?? [];
            unset($op['token_hash'], $op['owner'], $op['pid'], $op['pgid']);
            $log = $this->logTail((string) ($op['id'] ?? ''), 200);
            return GuardResponse::json(200, ['operation' => $op, 'log' => $log]);
        }
        if ($path === '/_update/recover' && $method === 'POST') {
            $in = json_decode($body, true);
            $option = is_array($in) ? (string) ($in['option'] ?? '') : '';
            if ($option === 'reopen' && (!is_array($in) || ($in['confirm'] ?? '') !== 'REOPEN')) {
                return GuardResponse::json(422, ['error' => 'confirm']);
            }
            return $this->ops->requestRecovery($token, $option)
                ? GuardResponse::json(202, ['requested' => $option])
                : GuardResponse::json(409, ['error' => 'not_recoverable']);
        }
        return GuardResponse::json(404, ['error' => 'not_found']);
    }

    /** @param array<string,string> $headers */
    private function verify(array $headers, string $body): GuardResponse
    {
        return GuardResponse::json(404, ['error' => 'not_found']); // Task 6
    }

    private function logTail(string $id, int $lines): string
    {
        $file = $id === '' ? '' : $this->paths->log($id);
        if ($file === '' || !is_file($file)) {
            return '';
        }
        $all = preg_split('/\r?\n/', rtrim((string) file_get_contents($file), "\n")) ?: [];
        return implode("\n", array_slice($all, -$lines));
    }

    private static function closedPage(): string
    {
        return '<!doctype html><meta charset="utf-8">'
            . '<meta name="viewport" content="width=device-width,initial-scale=1">'
            . '<title>Back in a few minutes</title>'
            . '<body style="font:16px system-ui;display:grid;place-items:center;min-height:90vh;margin:0 16px">'
            . '<main style="max-width:32rem;text-align:center"><h1 style="font-size:1.4rem">Back in a few minutes</h1>'
            . '<p>This site is being updated. Please try again shortly.</p></main>';
    }
}

// ---- entry ----
Guard::boot(dirname(__DIR__));
